    """The position (i, j) of the single cell of the given color."""
    return [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == color][0]

def inward_dir(grid, pos):
    """The unit step pointing from the given edge position into the grid."""
    h, w = len(grid), len(grid[0])
    i, j = pos
    if i == 0: return (1, 0)
    if i == h - 1: return (-1, 0)
    if j == 0: return (0, 1)
    return (0, -1)

def flow_through_gaps(grid, color=2):
    """From the seed cell, streams of color flow toward the 8-bars, splitting sideways when blocked and passing through each bar's gaps."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    si, sj = find_seed(grid, color)
    di, dj = inward_dir(grid, (si, sj))
    marked = {(si, sj)}
    stack, seen = [(si, sj)], {(si, sj)}
    while stack:
        i, j = stack.pop()
        ni, nj = i + di, j + dj
        if not (0 <= ni < h and 0 <= nj < w):
            continue
        if grid[ni][nj] != 8:
            if (ni, nj) not in seen:
                seen.add((ni, nj)); marked.add((ni, nj)); stack.append((ni, nj))
            continue
        for pi, pj in ((dj, di), (-dj, -di)):
            ci, cj = i, j
